    "Reap the Tides": {"route": "bigCreatures", "pace": "LAND RAMP AND SEA MONSTERS", "complexity": "Intermediate", "theme": "Aesi allows an extra land each turn and draws a card whenever your land enters.", "plan": "Build your mana with extra lands, then deploy sea monsters and bounce opposing creatures.", "mulligan": "Keep three lands and early ramp or an inexpensive creature that replaces itself.", "tip": "Aesi permits one additional land play; lands put onto the battlefield by effects do not use that allowance.", "keys": ["Trench Behemoth", "Stumpsquall Hydra", "Whelming Wave"]},
    "Phantom Premonition": {"route": "fliers", "pace": "FORETELL AND BLINK", "complexity": "Intermediate", "theme": "Ranar discounts your first foretell action each turn and creates Spirits from qualifying exile events.", "plan": "Set aside foretell spells, reuse creature entry abilities, and build a flying Spirit army.", "mulligan": "Keep two or three lands, a mana rock, and a foretell or blink play.", "tip": "Foretelling sets a card aside; it may be cast for its foretell cost only after that turn ends.", "keys": ["Ethereal Valkyrie", "Cosmic Intervention", "Soulherder"]},
    "Elven Empire": {"route": "typal", "pace": "ELVES AND LIFE DRAIN", "complexity": "Intermediate", "theme": "Lathril makes Elf Warriors from combat damage and taps an Elf army to drain the table.", "plan": "Develop mana Elves, attack with Lathril, and preserve enough untapped Elves for her drain ability.", "mulligan": "Keep two or three lands, a mana Elf, and an Elf payoff or card draw spell.", "tip": "Lathril taps herself plus ten other untapped Elves. The ten supporting Elves may have summoning sickness.", "keys": ["Marwyn, the Nurturer", "Pact of the Serpent", "Serpent's Soul-Jar"]},
