    "Dungeons of Death": {"route": "graveyard", "pace": "VENTURE AND REANIMATION", "complexity": "Intermediate", "theme": "Sefris ventures when creature cards enter your graveyard and reanimates after a dungeon.", "plan": "Put creatures in your graveyard, finish dungeons, and return impactful creatures with Sefris.", "mulligan": "Keep three lands, a way to draw or discard, and a venture or reanimation enabler.", "tip": "Sefris can venture only once each turn, including opponents’ turns. Completing a dungeon gives a separate targeted reanimation trigger.", "keys": ["Radiant Solar", "Hama Pashar, Ruin Seeker", "Midnight Pathlighter"]},
    "Aura of Courage": {"route": "equipment", "pace": "AURAS AND EQUIPMENT", "complexity": "Intermediate", "theme": "Galea casts Auras and Equipment from the top of your library.", "plan": "Establish a protected attacker, improve it with Auras and Equipment, and use Galea to keep cards flowing.", "mulligan": "Keep two or three lands, ramp, and an inexpensive Aura or Equipment.", "tip": "Equipment cast from the top with Galea gains an entry trigger that attaches it to a creature you control.", "keys": ["Mantle of the Ancients", "Holy Avenger", "Storvald, Frost Giant Jarl"]},
    "Draconic Rage": {"route": "bigCreatures", "pace": "DICE AND DRAGONS", "complexity": "Intermediate", "theme": "Vrondiss creates Dragon Spirits when dealt damage.", "plan": "Ramp into Dragons, use dice to trigger Vrondiss, and attack with the growing army.", "mulligan": "Keep three lands, ramp, and an affordable creature or dice effect.", "tip": "Vrondiss can deal 1 damage to himself whenever you roll dice; his Dragon Spirits are sacrificed after dealing damage.", "keys": ["Wulfgar of Icewind Dale", "Barbarian Class", "Klauth, Unrivaled Ancient"]},
    "Planar Portal": {"route": "exile", "pace": "EXILE AND TREASURE", "complexity": "Intermediate", "theme": "Prosper turns cards played from exile into Treasures.", "plan": "Build mana with Treasures, play exiled cards before permissions expire, and spend the extra resources on interaction.", "mulligan": "Keep two or three lands, early ramp, and a spell that exiles cards to play.", "tip": "Prosper lets you play his exiled card through the end of your next turn; normal timing and land limits still apply.", "keys": ["Wild-Magic Sorcerer", "Grim Hireling", "Fevered Suspicion"]},

