    "Exquisite Invention": {"route": "artifacts", "pace": "ARTIFACT ENGINES", "complexity": "Advanced", "theme": "Saheeli creates Servos and gives the next spell a discount based on your artifact count.", "plan": "Build artifact mana and tokens, protect Saheeli and turn spare machines into large threats or copied armies.", "mulligan": "Keep three lands, an artifact mana source and an early artifact.", "tip": "Choose between making a Servo and discounting your next spell. Each planeswalker normally activates once per turn.", "keys": ["Saheeli's Directive", "Brudiclad, Telchor Engineer", "Thopter Spy Network"]},
